func FormatExpression(e SsplitExpression) string {
	return fmt.Sprintf("%s = %.19g; components=%s; H72Compatible=%v native=%v", e.Expression, e.Value, strings.Join(e.Components, "+"), e.H72Compatible, e.NativeCertified)
}

func FormatComponent(c ComponentSource) string {
	return fmt.Sprintf("%s: %s; H72Scalar=%v native=%v bridgeHistory=%v", c.Name, c.Role, c.H72ScalarTyped, c.NativeCertified, c.BridgeHistoryUse)
}

func FormatCriteria(c NativeCriteria) string {
	return fmt.Sprintf("status=%s; required=%s; passed=%s; blocked=%s", c.Status, strings.Join(c.Required, ","), strings.Join(c.Passed, ","), strings.Join(c.Blocked, ","))
}

func FormatCertificate(c CertificateIIStatus) string {
	return fmt.Sprintf("%s; descent=%v sourceNative=%v certificatePassed=%v", c.Status, c.DescentSupported, c.SourceNative, c.CertificatePassed)
}

func containsAll(haystack, needles []string) bool {
	set := map[string]struct{}{}
	for _, h := range haystack {
		set[h] = struct{}{}
	}
	for _, n := range needles {
		if _, ok := set[n]; !ok {
			return false
		}
	}
	return true
}

func appendAll(items ...[]string) []string {
	var out []string
	for _, group := range items {
		out = append(out, group...)
	}
	return out
}

func componentSupports(components []ComponentSource) []string {
	var out []string
	for _, c := range components {
		out = append(out, c.Supports...)
	}
	return out
}

func componentFailures(components []ComponentSource) []string {
	var out []string
	for _, c := range components {
		out = append(out, c.Failures...)
	}
	return out
}

func stringsJoin(items []string) string { return strings.Join(items, " | ") }
